<?php
require_once __DIR__.'/../config/app.php';
function pageStart(string $title, string $subtitle = ''): void { ?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?> - SDN 1 UNDUOLO</title><link rel="stylesheet" href="<?=BASE_URL?>/assets/css/style.css"><link rel="stylesheet" href="<?=BASE_URL?>/assets/vendor/fontawesome/css/all.min.css"></head><body>
<a class="skip-link" href="#main">Lewati navigasi</a><div class="layout"><?php include __DIR__.'/sidebar.php'; ?><main class="layout__main" id="main">
<header class="page-header"><div><p class="eyebrow">SDN 1 UNDUOLO · <?=e(ucfirst($_SESSION['role']))?></p><h1><?=e($title)?></h1><?php if($subtitle):?><p class="muted"><?=e($subtitle)?></p><?php endif;?></div><span class="header-date"><?=date('d/m/Y')?> · WITA</span></header>
<?php if(isset($_SESSION['flash'])): [$m,$t]=$_SESSION['flash']; unset($_SESSION['flash']); ?><div class="message <?=e($t)?>" role="status"><?=e($m)?></div><?php endif;
}
function pageEnd(): void { ?><footer class="page-footer">SDN 1 UNDUOLO · Sistem Informasi Sekolah</footer></main></div><script src="<?=BASE_URL?>/assets/js/script.js"></script></body></html><?php }
function field(string $name,string $label,$value='',string $type='text',bool $required=true): void { ?><label class="form-group"><span><?=e($label)?></span><input name="<?=e($name)?>" type="<?=e($type)?>" value="<?=e($value)?>" <?=$required?'required':''?> <?= $type==='password'?'minlength="8" autocomplete="new-password"':''?>></label><?php }
function selectField(string $name,string $label,array $options,$selected='',bool $required=true): void { ?><label class="form-group"><span><?=e($label)?></span><select name="<?=e($name)?>" <?=$required?'required':''?>><option value=""><?=$required?'Pilih '.e($label):(str_starts_with($name,'presensi[')?'Belum dipresensi':(str_starts_with($name,'scores[')?'Belum dinilai':'—'))?></option><?php foreach($options as $v=>$l):?><option value="<?=e($v)?>" <?=(string)$v===(string)$selected?'selected':''?>><?=e($l)?></option><?php endforeach;?></select></label><?php }
function options(array $rows,string $label='nama',string $id='id'): array { return array_column($rows,$label,$id); }
function starField(int $studentId,string $studentName,$selected): void { ?>
<fieldset class="rating-widget"><legend class="sr-only">Penilaian <?=e($studentName)?></legend><div class="star-rating"><?php for($rating=5;$rating>=1;$rating--): $id='rating-'.$studentId.'-'.$rating;?><input type="radio" id="<?=$id?>" name="scores[<?=$studentId?>]" value="<?=$rating?>" <?=(int)$selected===$rating?'checked':''?>><label class="star-label" for="<?=$id?>"><span aria-hidden="true">★</span><span class="sr-only"><?=$rating?> bintang untuk <?=e($studentName)?></span></label><?php endfor;?></div></fieldset>
<?php }
function tableView(array $headers,array $rows,string $empty='Belum ada data untuk pilihan ini.'): void { ?><div class="table-wrapper" tabindex="0"><table><thead><tr><?php foreach($headers as $h):?><th scope="col"><?=e($h)?></th><?php endforeach;?></tr></thead><tbody><?php if(!$rows):?><tr><td class="empty-state" colspan="<?=count($headers)?>"><?=e($empty)?></td></tr><?php endif; foreach($rows as $row):?><tr><?php foreach($row as $cell):?><td><?=e($cell ?? '-')?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div><?php }
function stats(array $items): void { ?><div class="stats-grid"><?php foreach($items as $label=>$value):?><article class="card"><p class="card__title"><?=e($label)?></p><p class="card__value"><?=e($value)?></p></article><?php endforeach;?></div><?php }
function filterForm(array $fields): void { ?><form method="get" class="card filter-bar"><?php foreach($fields as $name=>$f){ if(is_array($f[1])) selectField($name,$f[0],$f[1],$_GET[$name]??($f[2]??''),false); else field($name,$f[0],$_GET[$name]??($f[2]??''),$f[1],false); }?><button class="btn">Terapkan</button><a class="btn btn--ghost" href="<?=e(strtok($_SERVER['REQUEST_URI'],'?'))?>">Reset</a></form><?php }
